raw_scene = res_raw.output.get("raw_scene", {})
print("raw_scene keys:", list(raw_scene.keys()))
segm_top = raw_scene.get("segm", {}).get("top")
if segm_top is not None:
    # Find min/max v for bounds (id 4) near u=120..135
    v_at_mid = []
    for v in range(128):
        for u in range(120, 136):
            if segm_top[v][u] == 4:
                v_at_mid.append(v)
    if v_at_mid:
        print("bounds top bar v range at u=120..135:", min(v_at_mid), max(v_at_mid))

# Check RGB colors of 6, 7, 8, 9 from raw_scene
rgb_top = raw_scene.get("rgb", {}).get("top")
for sid in [4, 5, 6, 7, 8, 9]:
    r_vals, g_vals, b_vals = [], [], []
    for v in range(128):
        for u in range(256):
            if segm_top[v][u] == sid:
                r_vals.append(int(rgb_top[0][v][u]))
                g_vals.append(int(rgb_top[1][v][u]))
                b_vals.append(int(rgb_top[2][v][u]))
    if r_vals:
        print(sid, "mean RGB:", sum(r_vals)//len(r_vals), sum(g_vals)//len(g_vals), sum(b_vals)//len(b_vals))

# Record evidence and push 6 & 7 slightly downward toward center of bounds (v=35..40) so they are well away from the back wall (v=9..18)
primitives.call(name="record_vima_evidence", key="swept_obj_ids", value=[6, 7])
primitives.call(name="record_vima_evidence", key="bounds_id", value=4)
primitives.call(name="record_vima_evidence", key="constraint_id", value=5)

# Push 6 and 7 from v=22 (x=0.336) down to v=36 (x=0.391) at u=127 (y=-0.004)
res_sub8 = primitives.call(
    name="submit_vima_action",
    pose0_position=[0.336, -0.004],
    pose0_rotation=[0.0, 0.0, 0.0, 1.0],
    pose1_position=[0.380, -0.004],
    pose1_rotation=[0.0, 0.0, 0.0, 1.0],
)
print("submit 8:", res_sub8.ok)

res_inst9 = primitives.call(name="inspect_vima_instances", view="top", min_pixel_count=1)
if res_inst9.ok:
    for inst in res_inst9.output.get("instances", {}).get("top", []):
        if inst["segmentation_id"] in [4, 5, 6, 7]:
            print("after 8:", inst)

